          throw new CliError(`找不到 sprint「${id}」，没法记评审证据`);
        }
        if (!Array.isArray(sprint.reviews)) sprint.reviews = [];
        sprint.reviews.push(data);
        await writeJson(root, rel, sprint, meta);
      } else {
        // 新增追加条目类型时必须在这里补规则，宁可当场报错也不瞎写
        throw new CliError(`写入类型「${type}」的追加规则还没实现，这是底座的漏洞，请报修`);
      }
      break;

    default:
      throw new CliError(`写入类型「${type}」声明的写入方式「${def.mode}」还没实现，这是底座的漏洞，请报修`);
  }
}

